local _, ns = ...
if ns.LOCALE ~= "deDE" then return end
local L = ns.L

-- Options/HelpPanes.lua: the FAQ and Support pages, beside Locales/deDE.lua.
L["FAQ_CAPTION"] = "Häufige Fragen und wo Dinge hin sind."
L["FAQ_SEARCH"] = "Fragen durchsuchen"
L["FAQ_NONE"] = "Keine Frage passt."
L["FAQ_NOT_BOUND"] = "nicht belegt"
L["FAQ_LFG_Q"] = "Wo ist meine LFG-Schaltfläche (Gruppensuche)?"
L["FAQ_LFG_A"] = "1.x hatte keine, darum fehlt sie im Mikromenü. Klick auf das Auge an der Minikarte, nutze die Seitenreiter im Wer-Reiter des Sozialfensters oder drück die Taste für die Gruppensuche (%s). Um die Schaltfläche zurückzuholen, entferne den Haken bei \"%s\" unter \"%s\"."
L["FAQ_LEGACY_Q"] = "Wo ist meine Vermächtnis-Taste?"
L["FAQ_LEGACY_A"] = "1.x hatte keine, deshalb ist sie nicht im Mikromenü. Klicke auf ihr Symbol an der Minikarte. Um die Taste zurückzuholen, entferne das Häkchen bei \"%s\" unter \"%s\". Jede Mikrotaste kann an der Minikarte sitzen: Hake sie unter \"%s\" an."
L["FAQ_PROFESSIONS_Q"] = "Wo ist meine Berufe-Schaltfläche?"
L["FAQ_PROFESSIONS_A"] = "1.x hatte keine, darum fehlt sie im Mikromenü. Öffne deine Berufe über das Zauberbuch oder drück die Taste für Berufe (%s). Um die Schaltfläche zurückzuholen, entferne den Haken bei \"%s\" unter \"%s\"."
L["FAQ_COLLECTIONS_Q"] = "Wo ist meine Sammlungen-Schaltfläche?"
L["FAQ_COLLECTIONS_A"] = "1.x hatte keine, darum fehlt sie im Mikromenü. Öffne Reittiere, Haustiere, Spielzeuge und Vorlagen über den Reiter \"%s\" am Fuß des Zauberbuchs oder drück die Taste für Sammlungen (%s). Um die Schaltfläche zurückzuholen, entferne den Haken bei \"%s\" unter \"%s\"."
L["FAQ_QUICKJOIN_Q"] = "Wo ist der Reiter „%s“?"
L["FAQ_QUICKJOIN_A"] = "Öffne im Sozialfenster %s und dann %s. Der Reiter %s unter der Liste wechselt dorthin, der Reiter %s wieder zurück."
L["FAQ_REAGENT_Q"] = "Wo ist meine Reagenzientasche?"
L["FAQ_REAGENT_A"] = "Sie ist die kleine runde Tasche zwischen Schlüsselbund und deiner letzten Tasche und erscheint, solange die Maus über deinen Taschen ist. Damit sie sichtbar bleibt, wähle \"%s\", oder \"%s\" für einen Platz wie die anderen Taschen."
L["FAQ_BARS_Q"] = "Wo sind die Aktionsleisten 6 bis 8?"
L["FAQ_BARS_A"] = "1.x hatte fünf Leisten. Die Leisten 6 bis 8 gehören dem Spiel: Schalte sie in seinen Optionen unter Aktionsleisten ein oder aus."
L["FAQ_TENBUTTONS_Q"] = "Warum zeigt meine Hauptleiste 10 Tasten oder die falsche Größe?"
L["FAQ_TENBUTTONS_A"] = "Das Band folgt den Einstellungen der Aktionsleiste 1 im Bearbeitungsmodus: \"%s\" und \"%s\". \"%s\" auf der Seite \"%s\" gibt dir die kleineren Tasten von 1.x."
L["FAQ_GRYPHONS_Q"] = "Wie blende ich die Greifen aus?"
L["FAQ_GRYPHONS_A"] = "Auf der Seite \"%s\" stellst du \"%s\" oder \"%s\" auf \"%s\". Im Bearbeitungsmodus ist jeder Greif ein eigenes Teil, das du verschieben oder ausblenden kannst."
L["FAQ_XPBAR_Q"] = "Kann ich die Erfahrungsleiste ausblenden oder vom Band lösen?"
L["FAQ_XPBAR_A"] = "Ja, im Bearbeitungsmodus. Klicke auf die Erfahrungs- oder Rufleiste: Sie lässt sich vom Band ziehen, und ihr Fenster hat \"%s\"."
L["FAQ_SIZE_Q"] = "Warum sind die Fenster kleiner als die des Spiels? Kann ich sie vergrößern?"
L["FAQ_SIZE_A"] = "Es sind die Größen von Classic Era. Klicke auf das Schloss in der Titelleiste eines Fensters und zieh den Griff in seiner Ecke, oder stell die Größe im Bearbeitungsmodus unter \"%s\" ein. Die Leisten folgen \"%s\" und der Größe im Bearbeitungsfenster jeder Leiste."
L["FAQ_SCALE_Q"] = "Warum ist meine Oberfläche größer geworden?"
L["FAQ_SCALE_A"] = "Classic Era zeichnet seine Oberfläche größer als Forever. Das klassische Layout mit Eras Größe stellt die UI-Skalierung des Spiels darauf ein, auf den meisten Bildschirmen 90%%. Ändern lässt sie sich jederzeit unter %s in den Optionen des Spiels („%s“)."
L["FAQ_SCALEBACK_Q"] = "Wie bekomme ich meine alte Oberflächengröße zurück?"
L["FAQ_SCALEBACK_A"] = "Drücke „%s“ in der Seitenleiste, mit Haken bei „%s“: Deine Größe von vorher kommt mit den Optionen zurück. Oder stelle sie unter %s in den Optionen des Spiels ein; ohne Haken bei „%s“ gilt die automatische Größe des Spiels."
L["FAQ_GLOW_Q"] = "Wie schalte ich das rote Leuchten an meinen Rahmen aus?"
L["FAQ_GLOW_A"] = "Auf der Seite \"%s\": \"%s\" für das rote Leuchten, wenn dich etwas angreift, \"%s\" für das Pulsieren deines Spielerrahmens, während du angreifst."
L["FAQ_TRACKER_Q"] = "Kann ich den alten Questtracker zurückhaben?"
L["FAQ_TRACKER_A"] = "Ja. Auf der Seite \"%s\" wählt \"%s\" sein Aussehen, darunter die Questbeobachtung von Classic Era."
L["FAQ_PLATES_Q"] = "Wie mache ich die Namensplaketten größer?"
L["FAQ_PLATES_A"] = "Ihre Größe stellt das Spiel selbst ein, unter \"%s\" in seinen Optionen. \"%s\" auf der Seite \"%s\" ändert nur den Namen."
L["FAQ_MOVE_Q"] = "Kann ich Fenster verschieben?"
L["FAQ_MOVE_A"] = "Ja, außerhalb des Kampfes. Fahr über die Titelleiste eines Fensters, klick auf sein Schloss und zieh es dann an der Titelleiste. Oder platziere Fenster im Bearbeitungsmodus unter \"%s\". Die rote Schaltfläche neben dem Schloss setzt ein Fenster an seinen Standardplatz zurück."
L["FAQ_MOVERS_Q"] = "Warum kann mein Fensterverschieber manche Fenster bewegen und andere nicht?"
L["FAQ_MOVERS_A"] = "Das Charakterfenster und andere Spielfenster sind die des Spiels im 1.x-Aussehen, deshalb können Fensterverschieber sie bewegen; \"%s\" in den Optionen überlässt sie ganz einem solchen Addon. Unser Zauberbuch und Questlog bauen wir selbst, weil das Spiel keine wie in Era hat, und Fensterverschieber bewegen nur Fenster auf ihrer eigenen Liste. Unsere bewegst du mit dem Schloss in ihrer Titelleiste oder im Bearbeitungsmodus."
L["FAQ_SETTING_Q"] = "Kann ich ändern, wie etwas aussieht oder funktioniert?"
L["FAQ_SETTING_A"] = "Sehr wahrscheinlich. Fast jedes Teil lässt sich ausschalten oder anpassen: Tippe ein Wort in das Feld \"%s\" oben links in diesem Fenster. Wenn du es nicht findest, frag auf GitHub oder CurseForge."
L["FAQ_FOREVER_Q"] = "Kann ich für einige Teile das eigene Aussehen von Forever behalten?"
L["FAQ_FOREVER_A"] = "Ja. Jedes klassische Teil hat seinen eigenen Schalter in diesem Fenster; schalte es aus und das von Forever kommt zurück. Manche Änderungen brauchen ein Neuladen, und ein Fenster fragt danach."
L["FAQ_OTHER_ADDON_Q"] = "Könnt ihr %s mit einem anderen Addon zusammenarbeiten lassen?"
L["FAQ_OTHER_ADDON_A"] = "Sag uns auf GitHub oder CurseForge, welches, und wir schauen es uns an. Wenn zwei Addons denselben Teil des Bildschirms umgestalten, funktionieren meist beide, sobald du diesen Teil hier ausschaltest."
L["FAQ_LFG_RETAIL_A"] = "1.x hatte keine, darum fehlt sie im Mikromenü. Klick auf das Auge an der Minikarte oder drück die Taste für die Gruppensuche (%s). Um die Schaltfläche zurückzuholen, entferne den Haken bei \"%s\" unter \"%s\"."
L["FAQ_REAGENT_RETAIL_A"] = "Sie steht am alten Platz des Schlüsselbunds, am Ende deiner Taschen. Für einen Platz wie die anderen Taschen wähle \"%s\"."
L["FAQ_OWNLOOK_Q"] = "Kann ich für einige Teile das eigene Aussehen des Spiels behalten?"
L["FAQ_OWNLOOK_A"] = "Ja. Jedes klassische Teil hat seinen eigenen Schalter in diesem Fenster; schalte es aus und das des Spiels kommt zurück. Manche Änderungen brauchen ein Neuladen, und ein Fenster fragt danach."
L["FAQ_RETAILBUTTONS_Q"] = "Wo sind meine Schaltflächen für %s, %s und %s?"
L["FAQ_RETAILBUTTONS_A"] = "1.x hatte keine, darum fehlen sie im Mikromenü. Klick auf ihre Symbole an der Minikarte oder drück die Taste für %s (%s) oder %s (%s). Um eine Schaltfläche zurückzuholen, entferne ihren Haken unter \"%s\"."
L["SUPPORT_CAPTION"] = "Danke, dass du %s nutzt."
L["SUPPORT_FEEDBACK_HEAD"] = "Rückmeldung"
L["SUPPORT_FEEDBACK"] = "Fehlerberichte, Ideen und jede andere Rückmeldung sind immer willkommen. Bevor du schreibst, drück bitte %s und füge ein, was es dir gibt: deine Einstellungen, die Spielversion und deine anderen Addons."
L["SUPPORT_POST"] = "Dann wähle, wo du es postest. Die Schaltflächen kopieren die Adresse zum Einfügen in deinen Browser."
L["SUPPORT_MORE_HEAD"] = "Das könnte dir auch gefallen"
L["SUPPORT_MORE"] = "EasyFind, ebenfalls von uns: eine Befehlspalette für das Spiel. Tippe ein, was du willst, und erledige es direkt aus den Ergebnissen: ein Fenster oder eine Einstellung öffnen, aufsitzen, einen Zauber wirken oder einen Ort auf der Karte finden."
L["SUPPORT_MORE_BUTTON"] = "EasyFind auf CurseForge"
L["SUPPORT_DONATE_HEAD"] = "Das Addon unterstützen"
L["SUPPORT_DONATE"] = "%s ist kostenlos. Wenn du es unterstützen möchtest, kannst du das über Buy Me a Coffee tun."
L["SUPPORT_DONATE_BUTTON"] = "Buy Me a Coffee"

-- Era's interface size (Options/EraScale.lua).
L["ERASCALE_OFFER"] = "Classic Era zeigt seine Oberfläche größer, als Forever es standardmäßig tut. Zur Größe von Era wechseln, mit den Leisten in klassischer Größe? Die Oberfläche wird neu geladen. Die Spieleinstellung %s ändert die Größe jederzeit."
L["ERASCALE_GIVEN_BACK"] = "Oberflächengröße zurückgesetzt. Sieht sie anders aus als erwartet? Klicke %s."
L["ERASCALE_HELP"] = "Die Oberflächengröße ist wieder die von vor dem klassischen Layout, oder die automatische Größe des Spiels. Wirkt sie noch zu groß oder zu klein, stelle sie unter %s in den Optionen des Spiels ein: ohne Haken bei „%s“ gilt die automatische Größe, sonst verschiebe ihren Regler."
L["ERASCALE_OPEN_SETTINGS"] = "Spieloptionen"
L["ERASCALE_SWITCH"] = "Größe von Era nutzen"
L["ERASCALE_ASK"] = "Deine Oberfläche ist auf diesem Bildschirm anders groß als in Classic Era. Zur Größe von Era wechseln, mit den Leisten in klassischer Größe? Die Spieleinstellung %s ändert sie jederzeit."
L["ERASCALE_KEEP"] = "Meine Größe behalten"
